function _labelNames(raw) {
    // ADO keeps tags as ONE string in System.Tags: "a; b; c".
    if (typeof raw === 'string' && raw.indexOf('[') !== 0) {
        return raw.split(';').map(function (x) { return x.trim(); }).filter(function (x) { return x; });
